// ---------------------------------------------------------------------------
// Phase 19.6 — the C# protocol is the TypeScript protocol (M6).
//
// apps/desktop-agent/contract is generated by the core package's tests from
// packages/core/src/desktop-agent.ts. Each test here fails if the agent's
// lists, limits, canonical strings, consent text, pairing codes, fingerprints
// or signatures stop matching it byte for byte.
// ---------------------------------------------------------------------------

using System.Text.Json;
using Jarvis.DesktopAgent.Core;
using Xunit;

namespace Jarvis.DesktopAgent.Core.Tests;

public class ContractTests
{
    private static readonly JsonElement Constants = Contract.Load("constants.json");
    private static readonly JsonElement Schemas = Contract.Load("schemas.json");
    private static JsonElement V => Contract.Vectors;

    private static List<string> Strings(JsonElement array) => array.EnumerateArray().Select(e => e.GetString()!).ToList();

    private static long Limit(string name) => Constants.GetProperty("limits").GetProperty(name).GetInt64();

    [Fact]
    public void Lists_and_versions_match_the_typescript_protocol()
    {
        Assert.Equal(ProtocolConstants.ProtocolVersion, Constants.GetProperty("protocolVersion").GetString());
        Assert.Equal(ProtocolConstants.AgentVersion, Constants.GetProperty("agentVersion").GetString());
        Assert.Equal(ProtocolConstants.CommandFormatVersion, Constants.GetProperty("commandFormatVersion").GetString());
        Assert.Equal(ProtocolConstants.ConsentTextVersion, Constants.GetProperty("consentTextVersion").GetString());
        Assert.Equal(ProtocolConstants.KillSwitch, Constants.GetProperty("killSwitch").GetString());
        Assert.Equal(Strings(Constants.GetProperty("commandActions")), ProtocolConstants.CommandActions);
        Assert.Equal(Strings(Constants.GetProperty("appIds")), ProtocolConstants.AppIds);
        Assert.Equal(Strings(Constants.GetProperty("helloActions")), ProtocolConstants.HelloActions);
        Assert.Equal(Strings(Constants.GetProperty("keyNames")), ProtocolConstants.KeyNames);
        Assert.Equal(Strings(Constants.GetProperty("mouseButtons")), ProtocolConstants.MouseButtons);
        Assert.Equal(Strings(Constants.GetProperty("errorCodes")), ProtocolConstants.ErrorCodes);
        Assert.Equal(Strings(Constants.GetProperty("notExecutedCodes")), ProtocolConstants.NotExecutedCodes);
        Assert.Equal(Strings(Constants.GetProperty("sessionEndReasons")), ProtocolConstants.SessionEndReasons);
    }

    [Fact]
    public void Limits_match_the_approved_decisions()
    {
        Assert.Equal(ProtocolConstants.PairingCodeTtlMs, Limit("pairingCodeTtlMs"));
        Assert.Equal(ProtocolConstants.CommandTtlMs, Limit("commandTtlMs"));
        Assert.Equal(ProtocolConstants.ClockSkewMs, Limit("clockSkewMs"));
        Assert.Equal(ProtocolConstants.GrantDefaultMinutes, Limit("grantDefaultMinutes"));
        Assert.Equal(ProtocolConstants.GrantMaxMinutes, Limit("grantMaxMinutes"));
        Assert.Equal(ProtocolConstants.ReconnectGraceMs, Limit("reconnectGraceMs"));
        Assert.Equal(ProtocolConstants.PollHoldMs, Limit("pollHoldMs"));
        Assert.Equal(ProtocolConstants.CoordinateMax, Limit("coordinateMax"));
        Assert.Equal(ProtocolConstants.TypeTextMaxLength, Limit("typeTextMaxLength"));
        Assert.Equal(ProtocolConstants.TypeFocusWaitMs, Limit("typeFocusWaitMs"));
        Assert.Equal(ProtocolConstants.Windows11FirstBuild, Limit("windows11FirstBuild"));
        // D6, U5a, U5b — fixed by the owner, not tunable.
        Assert.Equal(10 * 60_000, ProtocolConstants.PairingCodeTtlMs);
        Assert.Equal(30_000, ProtocolConstants.CommandTtlMs);
        Assert.Equal(60_000, ProtocolConstants.ClockSkewMs);
        Assert.Equal(15, ProtocolConstants.GrantDefaultMinutes);
        Assert.Equal(60, ProtocolConstants.GrantMaxMinutes);
        Assert.Equal(30_000, ProtocolConstants.ReconnectGraceMs);
    }

    [Fact]
    public void The_schemas_enumerate_the_same_values_the_agent_accepts()
    {
        var envelopes = Schemas.GetProperty("CommandEnvelope").GetProperty("anyOf").EnumerateArray().ToList();
        Assert.Equal(ProtocolConstants.CommandActions, envelopes.Select(e => e.GetProperty("properties").GetProperty("action").GetProperty("const").GetString()));
        var click = envelopes[0].GetProperty("properties").GetProperty("params").GetProperty("properties");
        Assert.Equal(ProtocolConstants.MouseButtons, Strings(click.GetProperty("button").GetProperty("enum")));
        Assert.Equal(ProtocolConstants.CoordinateMax, click.GetProperty("x").GetProperty("maximum").GetInt32());
        var key = envelopes[1].GetProperty("properties").GetProperty("params").GetProperty("properties");
        Assert.Equal(ProtocolConstants.KeyNames, Strings(key.GetProperty("key").GetProperty("enum")));
        var type = envelopes[2].GetProperty("properties").GetProperty("params").GetProperty("properties");
        Assert.Equal(ProtocolConstants.TypeTextMaxLength, type.GetProperty("text").GetProperty("maxLength").GetInt32());
        var launch = envelopes[3].GetProperty("properties").GetProperty("params").GetProperty("properties");
        Assert.Equal(ProtocolConstants.AppIds, Strings(launch.GetProperty("app").GetProperty("enum")));

        var error = Schemas.GetProperty("ErrorResponse").GetProperty("properties").GetProperty("error").GetProperty("properties");
        Assert.Equal(ProtocolConstants.ErrorCodes, Strings(error.GetProperty("code").GetProperty("enum")));
        var notExecuted = Schemas.GetProperty("CommandResult").GetProperty("anyOf").EnumerateArray()
            .Single(e => e.GetProperty("properties").GetProperty("outcome").GetProperty("const").GetString() == "not-executed");
        Assert.Equal(ProtocolConstants.NotExecutedCodes, Strings(notExecuted.GetProperty("properties").GetProperty("code").GetProperty("enum")));
        Assert.Equal(ProtocolConstants.SessionEndReasons, Strings(Schemas.GetProperty("SessionEndRequest").GetProperty("properties").GetProperty("reason").GetProperty("enum")));
    }

    [Fact]
    public void Every_message_object_is_closed()
    {
        foreach (var message in Schemas.EnumerateObject())
        {
            var variants = message.Value.TryGetProperty("anyOf", out var anyOf) ? anyOf.EnumerateArray().ToList() : [message.Value];
            foreach (var variant in variants)
                Assert.False(variant.GetProperty("additionalProperties").GetBoolean(), $"{message.Name} accepts unknown fields");
        }
    }

    [Fact]
    public void Request_canonical_strings_and_signatures_match()
    {
        var device = V.GetProperty("deviceKey").GetProperty("spki").GetString()!;
        foreach (var vector in V.GetProperty("requests").EnumerateArray())
        {
            var p = vector.GetProperty("parts");
            var canonical = Canonical.Request(
                p.GetProperty("method").GetString()!, p.GetProperty("path").GetString()!, p.GetProperty("timestamp").GetString()!,
                p.GetProperty("nonce").GetString()!, p.GetProperty("device").GetString()!, p.GetProperty("bodySha256").GetString()!);
            Assert.Equal(vector.GetProperty("canonical").GetString(), canonical);
            Assert.True(Signatures.Verify(device, canonical, vector.GetProperty("signature").GetString()));
            Assert.False(Signatures.Verify(device, canonical + "x", vector.GetProperty("signature").GetString()));
        }
    }

    [Fact]
    public void Command_canonical_strings_and_server_signatures_match_including_unicode_text()
    {
        foreach (var vector in V.GetProperty("commands").EnumerateArray())
        {
            var p = vector.GetProperty("parts");
            var raw = p.GetProperty("params");
            CommandParams parameters = raw.GetProperty("action").GetString() switch
            {
                ProtocolConstants.Click => new ClickParams(raw.GetProperty("x").GetInt32(), raw.GetProperty("y").GetInt32(), raw.GetProperty("button").GetString()!),
                ProtocolConstants.Key => new KeyParams(raw.GetProperty("key").GetString()!),
                ProtocolConstants.AppLaunch => new LaunchParams(raw.GetProperty("app").GetString()!),
                _ => new TypeParams(raw.GetProperty("text").GetString()!),
            };
            var envelope = new CommandEnvelope(
                p.GetProperty("commandId").GetString()!, p.GetProperty("deviceId").GetString()!, p.GetProperty("grantId").GetString()!,
                parameters, p.GetProperty("issuedAt").GetInt64(), p.GetProperty("expiresAt").GetInt64(), p.GetProperty("requiresHello").GetBoolean(),
                vector.GetProperty("signature").GetString()!);
            Assert.Equal(vector.GetProperty("paramsCanonical").GetString(), Canonical.Params(parameters));
            Assert.Equal(vector.GetProperty("canonical").GetString(), Canonical.Command(envelope));
            Assert.True(Signatures.Verify(Contract.ServerSpki, Canonical.Command(envelope), envelope.Signature));
        }
    }

    [Fact]
    public void Response_canonical_strings_and_signatures_match()
    {
        foreach (var vector in V.GetProperty("responses").EnumerateArray())
        {
            var body = vector.GetProperty("body").GetString()!;
            Assert.Equal(vector.GetProperty("bodySha256").GetString(), Canonical.Sha256Hex(body));
            var canonical = Canonical.Response(vector.GetProperty("requestNonce").GetString()!, vector.GetProperty("status").GetInt32(), Canonical.Sha256Hex(body));
            Assert.Equal(vector.GetProperty("canonical").GetString(), canonical);
            Assert.True(Signatures.Verify(Contract.ServerSpki, canonical, vector.GetProperty("signature").GetString()));
        }
    }

    [Fact]
    public void Consent_text_renders_byte_for_byte_and_hashes_alike()
    {
        foreach (var vector in V.GetProperty("consent").EnumerateArray())
        {
            var text = ConsentText.Render(
                vector.GetProperty("userLabel").GetString()!, vector.GetProperty("organizationLabel").GetString()!,
                vector.GetProperty("durationMinutes").GetInt32(), Strings(vector.GetProperty("scope")));
            Assert.Equal(vector.GetProperty("text").GetString(), text);
            Assert.Equal(vector.GetProperty("sha256").GetString(), ConsentText.Sha256(text));
        }
    }

    [Fact]
    public void Pairing_codes_normalize_and_hash_alike()
    {
        foreach (var vector in V.GetProperty("pairingCodes").EnumerateArray())
        {
            var normalized = PairingCode.Normalize(vector.GetProperty("input").GetString());
            Assert.Equal(vector.GetProperty("normalized").GetString(), normalized);
            Assert.Equal(vector.GetProperty("hash").GetString(), PairingCode.Hash(normalized!));
        }
        Assert.Null(PairingCode.Normalize("7K3M-Q9X2"));
        Assert.Null(PairingCode.Normalize("UUUUUUUUUUUUUUUUUUUUUUUUUUUUUUUU"));
    }

    [Fact]
    public void Fingerprints_and_key_ids_match()
    {
        var device = V.GetProperty("deviceKey");
        Assert.Equal(device.GetProperty("fingerprint").GetString(), Fingerprint.Of(device.GetProperty("spki").GetString()!));
        Assert.Equal(device.GetProperty("display").GetString(), Fingerprint.Display(device.GetProperty("fingerprint").GetString()!));
        Assert.Equal(Contract.ServerKeyId, Fingerprint.ServerKeyId(Contract.ServerSpki));
    }
}
